/// region-relative offsets of the 8 records of loan call #14,286 that name Z0 (lane swap Z0 -> the Y239 lane)
pub const Z0_OFFS: [u32; 8] = [58425434, 58425435, 58425568, 58425569, 58426007, 58426008, 58426141, 58426142];
/// his ids: H1, Z0, Y239
pub const ID_H1: usize = 642;
pub const ID_Z0: usize = 512;
pub const ID_S: usize = 495;
#[derive(Debug, Default, Clone)]
pub struct Stats { pub noop: usize, pub z0: usize }
/// rewrite one forward region's rows in place (rows = exactly the region's FWD_LEN rows); h1 / z0 / s = the lanes of ids 642 / 512
/// / 495 in the region (identical before and after the i1 relabelling: the relabelling hides lane 632 on lane 498 over the region)
pub fn rewrite_region(rows: &mut [Row], h1: u16, z0: u16, s: u16) -> Stats {
    assert!(rows.len() as u64 == hybrid::FWD_LEN, "flwalk: region length {}", rows.len());
    assert!(rows.iter().all(|r| (1..=super::super::qubits(r[0])).all(|j| r[j] != s)), "flwalk: the substitute lane {} is named in the region", s);
    let mut st = Stats::default(); let mut o = 0usize;
    for &d in NOOP_DELTAS.iter() { o += d as usize; let r = rows[o];
        assert!(r[0] == 8 && r[1] == h1 && r[3] == NONE, "flwalk: record +{} is {:?}, expected CX {} -> x", o, r, h1);
        rows[o] = [4, SCR, NONE, NONE]; st.noop += 1; }
    for &o in Z0_OFFS.iter() { let o = o as usize; let r = &mut rows[o];
        assert!(r[0] == 13 && (r[1] == z0 || r[2] == z0 || r[3] == z0), "flwalk: record +{} is {:?}, expected a CCX naming {}", o, r, z0);
        for j in 1..=3 { if r[j] == z0 { r[j] = s; } } st.z0 += 1; }
    st
}
/// the integrator's hook: rewrite both forward regions of the hybrid-spliced list (positions of hybrid::layout(), i.e. before the i1
/// relabelling and before any later splice that moves them; `seg_map(seg)` = the region's id -> lane map)
pub fn apply_layout<S: Slot>(out: &mut [S], seg_map: &dyn Fn(usize) -> Vec<u16>) -> Vec<Stats> {
    let lay = hybrid::layout(); let mut v = Vec::new();
    for (r, l) in hybrid::REGIONS.iter().zip(lay.iter()) { if !r.fwd { continue; }
        let m = seg_map(r.seg); let (s, e) = (l.2 as usize, (l.2 + l.3) as usize);
        let mut rows: Vec<Row> = out[s..e].iter().map(|x| x.to_row()).collect();
        let st = rewrite_region(&mut rows, m[ID_H1], m[ID_Z0], m[ID_S]);
        for (i, r) in rows.into_iter().enumerate() { out[s + i] = S::from_row(r); }
        v.push(st); }
    v
}
